
.form-card {
  width: 100%;
  max-width: 680px;
  background-color: var(--c-surface-warm);
  border: 2px solid var(--c-border);
  border-radius: 14px;
  box-shadow: 0 4px 16px rgba(90, 74, 66, 0.10);
  font-family: var(--font-main);
  color: var(--c-text);
  font-size: 13px;
  margin: 0 auto;
  overflow: hidden;
}

.form-header {
  padding: 12px 14px;
  background: linear-gradient(135deg, var(--c-primary), var(--c-accent));
}

.form-title {
  display: block;
  font-size: 16px;
  font-weight: 700;
  color: #fff;
  letter-spacing: 1px;
}

.form-sub {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.85);
}

.candidates {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  padding: 12px 14px;
}

.form-actions {
  display: flex;
  justify-content: center;
  padding: 0 14px 14px;
}

.btn-reroll {
  padding: 6px 18px;
  border: 1px solid var(--c-primary-deep);
  border-radius: 16px;
  background: #fff;
  color: var(--c-primary-deep);
  font-family: inherit;
  font-size: 12px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-reroll:hover {
  background: var(--c-primary-deep);
  color: #fff;
}
